from pathlib import Path
p=Path('outputs/index.html');s=p.read_text(encoding='utf-8')
# Square lattice and snapped subject positions
s=s.replace("for(let x=25;x<W;x+=35){cx.beginPath();cx.moveTo(x,20);cx.lineTo(x,H-20);cx.stroke()}for(let y=20;y<H;y+=35){cx.beginPath();cx.moveTo(20,y);cx.lineTo(W-20,y);cx.stroke()}", "cx.strokeStyle=dark?'#283a45':'#344852';for(let x=20;x<W-20;x+=45){cx.beginPath();cx.moveTo(x,20);cx.lineTo(x,H-20);cx.stroke()}for(let y=20;y<H-20;y+=45){cx.beginPath();cx.moveTo(20,y);cx.lineTo(W-20,y);cx.stroke()}")
s=s.replace("function posFor(i,n){const spots=[[95,85],[500,63],[905,85],[930,297],[905,510],[500,532],[95,510],[70,297]];let ix=Math.floor(i*8/n);return{x:spots[ix][0],y:spots[ix][1]}}", "function posFor(i,n){const spots=[[95,85],[500,63],[905,85],[930,297],[905,510],[500,532],[95,510],[70,297]];let ix=Math.floor(i*8/n),q=spots[ix];return{x:42.5+Math.round((q[0]-42.5)/45)*45,y:42.5+Math.round((q[1]-42.5)/45)*45}}")
