# Overlay combat action choices with explicit escape routing
old='<div class="controls"><button class="control" data-action="block" aria-pressed="false"><strong>GUARD</strong>Brace against incoming strikes</button><button class="control" data-action="attack" aria-pressed="false"><strong>STRIKE</strong>A focused blow at one opponent</button><button class="control" data-action="special" aria-pressed="false"><strong>SIGNATURE</strong>A sweeping attack against every opponent</button></div>'
new='''<div class="combatActions" id="combatActions" role="group" aria-label="Combat choices"><button class="control" data-action="block" aria-pressed="false"><strong>GUARD</strong>Brace against incoming strikes</button><button class="control" data-action="attack" aria-pressed="false"><strong>STRIKE</strong>A focused blow at one opponent</button><button class="control" data-action="special" aria-pressed="false"><strong>SIGNATURE</strong>A sweeping attack against every opponent</button><button class="control" data-action="escape" aria-pressed="false"><strong>ESCAPE</strong>Run clear of the engagement</button></div><div class="escapeControls hidden" id="escapeControls" role="group" aria-label="Escape route"><span class="eyebrow">CHOOSE YOUR ESCAPE ROUTE</span><p id="escapeHelp">Select how far to run and the direction. Your route is shown on the arena.</p><div class="escapeDistances"><button data-escape-distance="1" aria-pressed="true">1 SQUARE</button><button data-escape-distance="2" aria-pressed="false">2 SQUARES</button><button data-escape-distance="3" aria-pressed="false">3 SQUARES</button></div><div class="escapeDirs" role="group" aria-label="Escape direction"><button data-escape-dir="0,-1" aria-label="Escape north" aria-pressed="true">↑ NORTH</button><button data-escape-dir="-1,0" aria-label="Escape west" aria-pressed="false">← WEST</button><button data-escape-dir="0,1" aria-label="Escape south" aria-pressed="false">↓ SOUTH</button><button data-escape-dir="1,0" aria-label="Escape east" aria-pressed="false">→ EAST</button></div><div class="escapeButtons"><button id="cancelEscape">BACK TO ACTIONS</button><button class="primary" id="confirmEscape">ESCAPE</button></div></div>'''
if old not in s: print('combat action markup not found')
else: s=s.replace(old,new,1)
