s=s.replace("state.deadline=Date.now()+5000;state.players.filter(p=>p.bot", "state.deadline=Date.now()+6000;state.players.filter(p=>p.bot",1)
s=s.replace("sendState();setTimeout(resolveMoves,5000)", "sendState();setTimeout(resolveMoves,6000)",1)
