s=s.replace("state.deadline=Date.now()+3000;state.fighters.filter", "state.combatTurn=(state.combatTurn||1)+1;state.deadline=Date.now()+6000;state.fighters.filter",1)
s=s.replace("setTimeout(()=>{if(host&&state.phase==='combat')resolveCombat()},3000)", "setTimeout(()=>{if(host&&state.phase==='combat')resolveCombat()},6000)")
