# Replace path-of-dots with highlighted traversed / landing tiles
old_preview="""if(state.phase==='move'){let mep=state.players.find(p=>p.id===me?.id&&p.alive&&!p.contained);if(mep){let steps=moveChoice==='wait'?0:Number(moveChoice),dx=moveDir.x*45,dy=moveDir.y*45;cx.save();cx.strokeStyle='#54f3e1';cx.fillStyle='#54f3e1';cx.lineWidth=3;cx.setLineDash([7,5]);cx.beginPath();cx.moveTo(mep.x,mep.y+12);cx.lineTo(mep.x+dx*steps,mep.y+12+dy*steps);cx.stroke();cx.setLineDash([]);for(let k=1;k<=steps;k++){cx.globalAlpha=k===steps?1:.38;cx.beginPath();cx.arc(mep.x+dx*k,mep.y+12+dy*k,k===steps?10:5,0,Math.PI*2);cx.fill()}cx.globalAlpha=1;cx.restore()}}"""
new_preview="""if(state.phase==='move'){let mep=state.players.find(p=>p.id===me?.id&&p.alive&&!p.contained);if(mep)drawTilePreview(mep,moveChoice==='wait'?0:Number(moveChoice),moveDir)}if(state.phase==='combat'&&escapeSelecting){let mep=state.players.find(p=>p.id===me?.id&&p.alive);if(mep)drawTilePreview(mep,escapeDistance,escapeDir)}"""
if old_preview not in s: print('old route preview not found')
else:s=s.replace(old_preview,new_preview,1)
# Make all movement use same square collision model
s=s.replace("obstacles().some(o=>x>o.x-20&&x<o.x+o.w+20&&y>o.y-20&&y<o.y+o.h+20)", "tileBlocked(x,y)")
# Add grid helpers before draw
needle='function draw(){'
helpers="""function tileBlocked(x,y){const half=22.5;if(x-half<20||x+half>980||y-half<20||y+half>575)return true;return obstacles().some(o=>x+half>o.x&&x-half<o.x+o.w&&y+half>o.y&&y-half<o.y+o.h)}function drawTilePreview(p,steps,dir){cx.save();for(let k=1;k<=steps;k++){let x=p.x+dir.x*45*k,y=p.y+dir.y*45*k,blocked=tileBlocked(x,y),last=k===steps;cx.fillStyle=blocked?'rgba(255,55,70,.35)':last?'rgba(84,243,225,.43)':'rgba(84,243,225,.23)';cx.strokeStyle=blocked?'#ff5966':last?'#8dfff3':'#54f3e1';cx.lineWidth=last?3:2;cx.fillRect(x-21,y-21,42,42);cx.strokeRect(x-21,y-21,42,42);cx.fillStyle=blocked?'#ffd5d9':'#e8fffc';cx.font='bold 8px IBM Plex Mono';cx.textAlign='center';cx.fillText(blocked?'BLOCKED':last?'LAND':String(k),x,y+3);if(blocked)break}cx.textAlign='left';cx.restore()}"""
s=s.replace(needle,helpers+needle,1)
p.write_text(s,encoding='utf-8')
